import React, { useState } from "react";
import axios from "axios";

const RoleSelection = ({ onRoleSelected }) => {
  const [selectedRole, setSelectedRole] = useState(null);
  const [subRole, setSubRole] = useState("");
  const [customPurpose, setCustomPurpose] = useState("");

  // Crisp descriptions for each main role
  const roleDescriptions = {
    Student:
      "For learners in schools or colleges who want a secure place to manage study notes, schedules, and personal reflections.",
    Professional:
      "For working individuals like doctors, engineers, or teachers who need a safe diary for tasks, meetings, and confidential notes.",
    Homemaker:
      "For parents or caregivers managing household tasks, budgets, and personal journaling in a secure space.",
    Retired:
      "For seniors and retired individuals to track activities, reflections, and memories securely.",
    Custom:
      "For users who want to define their own unique purpose for using this secure e-diary."
  };

  // Suboptions for each role (3 + optional "Other")
  const subOptions = {
    Student: ["High School", "College", "Other"],
    Professional: ["Doctor", "Engineer", "Teacher", "Other"],
    Homemaker: ["Parent", "Caregiver", "Writer", "Other"],
    Retired: ["Senior Citizen", "Volunteer", "Mentor", "Other"]
    // Custom won't have predefined subRoles → it will show input box
  };

  const handleSubmit = async () => {
    if (!selectedRole) return alert("Please select a role.");

    try {
      await axios.put("http://localhost:5000/api/role", {
        role: selectedRole,
        subRole: subRole || "",
        customPurpose: selectedRole === "Custom" ? customPurpose : ""
      });

      onRoleSelected(selectedRole, subRole, customPurpose);
    } catch (err) {
      console.error("Error saving role:", err);
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center bg-gray-100 p-6">
      <h1 className="text-2xl font-bold mb-6">Select Your Role</h1>

      {/* Main role buttons */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-6">
        {Object.keys(roleDescriptions).map((role) => (
          <div
            key={role}
            onClick={() => {
              setSelectedRole(role);
              setSubRole("");
              setCustomPurpose("");
            }}
            className={`p-6 rounded-2xl shadow-md cursor-pointer transition ${
              selectedRole === role ? "bg-blue-500 text-white" : "bg-white"
            }`}
          >
            <h2 className="text-xl font-semibold mb-2">{role}</h2>
            <p className="text-sm">{roleDescriptions[role]}</p>
          </div>
        ))}
      </div>

      {/* Suboptions when a role is selected */}
      {selectedRole && subOptions[selectedRole] && (
        <div className="mb-6">
          <h3 className="text-lg font-medium mb-2">Choose a sub-role:</h3>
          <div className="flex gap-4 flex-wrap">
            {subOptions[selectedRole].map((option) => (
              <button
                key={option}
                onClick={() => setSubRole(option)}
                className={`px-4 py-2 rounded-xl border ${
                  subRole === option
                    ? "bg-green-500 text-white"
                    : "bg-gray-200"
                }`}
              >
                {option}
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Custom Purpose input box */}
      {selectedRole === "Custom" && (
        <div className="mb-6 w-full max-w-md">
          <h3 className="text-lg font-medium mb-2">
            Define your custom purpose:
          </h3>
          <input
            type="text"
            value={customPurpose}
            onChange={(e) => setCustomPurpose(e.target.value)}
            placeholder="e.g., Travel Journal, Startup Ideas, Therapy Notes"
            className="w-full px-4 py-2 rounded-xl border border-gray-300 focus:ring-2 focus:ring-blue-500"
          />
        </div>
      )}

      {/* Submit */}
      <button
        onClick={handleSubmit}
        className="px-6 py-3 rounded-xl bg-blue-600 text-white font-semibold hover:bg-blue-700"
      >
        Continue
      </button>
    </div>
  );
};

export default RoleSelection;
